typedef struct {
  void *err, *mem, *progress, *client_data;
  int is_decompressor, global_state;
  void *src;
  unsigned image_width, image_height;
  int num_components, jpeg_color_space, out_color_space;
  unsigned scale_num, scale_denom;
  double output_gamma;
  int buffered_image, raw_data_out, dct_method, do_fancy_upsampling, do_block_smoothing;
  int quantize_colors, dither_mode, two_pass_quantize, desired_number_of_colors;
  int enable_1pass_quant, enable_external_quant, enable_2pass_quant;
  unsigned output_width, output_height;
  int out_color_components, output_components, rec_outbuf_height;
  int actual_number_of_colors;
  unsigned char **colormap;
  unsigned output_scanline;
  unsigned char reserved[4096];
} Decoder;
extern void *jpeg_std_error(void *);
extern void jpeg_CreateDecompress(void *, int, size_t);
extern void jpeg_stdio_src(void *, FILE *);
extern int jpeg_read_header(void *, int);
extern int jpeg_start_decompress(void *);
extern unsigned jpeg_read_scanlines(void *, unsigned char **, unsigned);
extern int jpeg_finish_decompress(void *);
extern void jpeg_destroy_decompress(void *);
int main(int argc,char**argv) {
  if(argc<2)return 1;
  union { max_align_t a; unsigned char bytes[1024]; } err={0};
  Decoder c={0};c.err=jpeg_std_error(err.bytes);
  jpeg_CreateDecompress(&c,80,656);
  FILE *f=fopen(argv[1],"rb");if(!f)return 1;
  jpeg_stdio_src(&c,f);jpeg_read_header(&c,1);
  fprintf(stderr,"Source: %u %u %d colorspace %d out_color_space %d scale %d/%d\n",c.image_width,c.image_height,c.num_components,c.jpeg_color_space,c.out_color_space,c.scale_num,c.scale_denom);
  jpeg_start_decompress(&c);
  fprintf(stderr,"Output: %u %u %d Scanline %u\n",c.output_width,c.output_height,c.output_components,c.output_scanline);
  unsigned char *row=malloc(c.output_width*c.output_components);
  printf("P%d\n%u %u\n255\n",c.output_components==1?5:6,c.output_width,c.output_height);
  while(c.output_scanline<c.output_height) { jpeg_read_scanlines(&c,&row,1); fwrite(row,c.output_components,c.output_width,stdout); }
  jpeg_finish_decompress(&c);jpeg_destroy_decompress(&c);free(row);fclose(f);
}
