#include "jpeg_compat.h"
#include <math.h>
#include <string.h>
static const char *chars="   ...',;:clodxkO0KXNWM";
typedef struct {float r,g,b,l;} Pixel;
int main(int argc,char**argv) {
 if(argc<4)return 1;
 int ow=atoi(argv[2]),oh=atoi(argv[3]);
 union {max_align_t a;char data[1024];}err={0};Decoder c={0};
 c.err=jpeg_std_error(err.data);jpeg_CreateDecompress(&c,80,656);
 FILE *f=fopen(argv[1],"rb");if(!f)return 1;
 jpeg_stdio_src(&c,f);jpeg_read_header(&c,1);jpeg_start_decompress(&c);
 int sw=c.output_width,sh=c.output_height,nc=c.output_components;
 unsigned char *data=malloc(sw*sh*nc);
 while(c.output_scanline<c.output_height){unsigned char*r=data+c.output_scanline*sw*nc;jpeg_read_scanlines(&c,&r,1);}
 jpeg_finish_decompress(&c);jpeg_destroy_decompress(&c);fclose(f);
 Pixel *horiz=calloc(sw*sh+ow*sh,sizeof(Pixel)),*out=calloc(ow*oh,sizeof(Pixel));
 for(int y=0;y<sh;y++)for(int x=0;x<ow;x++) {
  int lo=lroundf((sw-1)*(float)x/ow),hi=lroundf((sw-1)*(float)(x+1)/ow);
  Pixel p={0};
  for(int sx=lo;sx<=hi;sx++){
   unsigned char*q=data+(y*sw+sx)*nc;
   float r=q[0]/255.0f,g=nc==1?r:q[1]/255.0f,b=nc==1?r:q[2]/255.0f;
   p.r+=r;p.g+=g;p.b+=b;p.l+=nc==1?r:r*.2989f+g*.5866f+b*.1145f;
  }
  float n=hi-lo+1;p.r/=n;p.g/=n;p.b/=n;p.l/=n;
  horiz[y*ow+x]=p;
 }
 if(sh>1) {
  int start=0,old=0;
  for(int sy=1;sy<sh;sy++){
   int dy=lroundf((oh-1)*(float)sy/(sh-1));
   if(dy>old) {
    for(int x=0;x<ow;x++){
     Pixel p={0};for(int z=start;z<=sy;z++){Pixel q=horiz[z*ow+x];p.r+=q.r;p.g+=q.g;p.b+=q.b;p.l+=q.l;}
     float n=sy-start+1;p.r/=n;p.g/=n;p.b/=n;p.l/=n;out[old*ow+x]=p;
     for(int y=old+1;y<dy;y++)out[y*ow+x]=horiz[sy*ow+x];
    }
    start=sy;old=dy;
   }
  }
  for(int x=0;x<ow;x++) {
   Pixel p={0};for(int z=start;z<sh;z++){Pixel q=horiz[z*ow+x];p.r+=q.r;p.g+=q.g;p.b+=q.b;p.l+=q.l;}
   float n=sh-start;p.r/=n;p.g/=n;p.b/=n;p.l/=n;out[old*ow+x]=p;
  }
 }
 for(int y=0;y<oh;y++) {
  for(int x=0;x<ow;x++){
   Pixel p=out[y*ow+x];char ch=chars[(int)lroundf(p.l*(strlen(chars)-1))];
   if(argc>4)printf("<span style='color:#%02x%02x%02x;'>%s%c%s</span>",(int)lroundf(255*p.r),(int)lroundf(255*p.g),(int)lroundf(255*p.b),ch==' '?"&nbsp;":"",ch==' '?0:ch,"");
   else putchar(ch);
  }
  printf(argc>4?"<br/>":"\n");
 }
 return 0;
}
