}
static int match(const char *s, const char *a, const char *b) {
    return !strcmp(s,a) || (b && !strcmp(s,b));
}
static void parse(int argc, char **argv) {
    memset(&opt,0,sizeof opt);
    opt.red=.2989f; opt.green=.5866f; opt.blue=.1145f;
    opt.chars="   ...',;:clodxkO0KXNWM";
    opt.title="jp2a converted image"; opt.output="-";
    opt.bold=1; opt.fontsize=8; opt.terminal=FIT;
    opt.files=calloc((size_t)argc,sizeof(char*));
    for(int i=1;i<argc;i++) {
        char *s=argv[i]; int w,h,n; float f;
        if(s[0]!='-' || !strcmp(s,"-")) { opt.files[opt.file_count++]=s; continue; }
        if(match(s,"--help","-h")) { usage(); exit(0); }
        else if(match(s,"--version","-V")) { version(); exit(0); }
        else if(match(s,"--invert","-i")) opt.invert=!opt.invert;
        else if(!strcmp(s,"--background=dark")) opt.invert=0;
        else if(!strcmp(s,"--background=light")) opt.invert=1;
        else if(match(s,"--border","-b")) opt.border=1;
        else if(match(s,"--flipx","-x")) opt.flipx=1;
        else if(match(s,"--flipy","-y")) opt.flipy=1;
        else if(match(s,"--verbose","-v")) opt.verbose=1;
        else if(match(s,"--debug","-d")) opt.debug=1;
        else if(match(s,"--term-fit","-f")) opt.terminal=FIT;
        else if(!strcmp(s,"--term-width")) opt.terminal=TERM_WIDTH;
        else if(!strcmp(s,"--term-height")) opt.terminal=TERM_HEIGHT;
        else if(match(s,"--term-zoom","-z")) opt.terminal=ZOOM;
        else if(match(s,"--colors","--color")) opt.colors=1;
        else if(!strcmp(s,"--grayscale")) opt.grayscale=1;
        else if(!strcmp(s,"--clear")) opt.clear=1;
        else if(!strcmp(s,"--fill")) opt.fill=1;
        else if(!strcmp(s,"--html-fill")) { opt.fill=1; fputs("warning: --html-fill has changed to --fill\n",stderr); }
        else if(!strcmp(s,"--html")) opt.html=1;
        else if(!strcmp(s,"--html-raw")) opt.raw=1;
        else if(!strcmp(s,"--html-no-bold")) opt.bold=0;
        else if(!strncmp(s,"--html-title=",13)) opt.title=s+13;
        else if(!strncmp(s,"--chars=",8)) opt.chars=s+8;
        else if(!strncmp(s,"--output=",9)) opt.output=s+9;
        else if(sscanf(s,"--html-fontsize=%d",&n)==1) opt.fontsize=n;
        else if(sscanf(s,"--red=%f",&f)==1) opt.red=f;
        else if(sscanf(s,"--green=%f",&f)==1) opt.green=f;
        else if(sscanf(s,"--blue=%f",&f)==1) opt.blue=f;
        else if(sscanf(s,"--size=%dx%d",&w,&h)==2) {
            opt.width=w; opt.height=h; opt.have_width=opt.have_height=1;
            opt.had_size=1; opt.height_count=0;
