        else if(sscanf(s,"--width=%d",&w)==1) {
            opt.width=w;
            if(opt.had_size) { if(opt.height_count==0) opt.have_height=0; opt.have_width=1; }
            else opt.have_width=1;
        }
        else if(sscanf(s,"--height=%d",&h)==1) {
            opt.height=h; opt.have_height=1; opt.height_count++;
            if(opt.had_size) opt.have_width=0;
        }
        else unknown(s);
    }
    if(!opt.file_count) { fputs("No files specified.\n\n",stderr); usage(); exit(1); }
    opt.using_terminal=(opt.width==0 && opt.height==0) || opt.terminal!=FIT;
    if(opt.using_terminal) {
        const char *t=getenv("TERM");
        if(!t) die("Environment variable TERM not set.\n");
        int result=0;
        if(setupterm((char*)t, STDOUT_FILENO, &result)==ERR || result!=1) {
