    }
    if(strlen(opt.chars)<2) die("You must specify at least two characters in --chars.\n");
    if(opt.red+opt.green+opt.blue!=1.0f) die("Weights RED + GREEN + BLUE must equal 1.0\n");
    if(opt.width<0 || opt.height<0 ||
       (opt.had_size && !opt.using_terminal && opt.have_width && opt.have_height && (!opt.width || !opt.height)) ||
       (opt.have_height && !opt.height && opt.terminal==FIT) ||
       (opt.have_width && !opt.width && opt.height && opt.terminal==FIT) ||
       (!opt.have_width && opt.height_count==2 && !opt.had_size))
        die("Invalid width or height specified\n");
    if(!*opt.output) die("Empty output filename.\n");
