static void dimensions(unsigned sw,unsigned sh,int *w,int *h) {
    float ratio=(float)sw/sh;
    *w=opt.width; *h=opt.height;
    int mode=0; /* 0: exact; 1: width specified; 2: height specified */
    if(opt.using_terminal) {
        if(opt.terminal==ZOOM) {*w=opt.term_cols;*h=opt.term_rows;}
        else if(opt.terminal==TERM_WIDTH) {*w=opt.term_cols;mode=1;}
        else if(opt.terminal==TERM_HEIGHT) {*h=opt.term_rows;mode=2;}
        else {
            if(opt.term_cols/(2.0f*ratio)<=opt.term_rows) {*w=opt.term_cols;mode=1;}
            else {*h=opt.term_rows;mode=2;}
        }
    } else if(opt.had_size) {
        if(opt.height_count>0) mode=2;
        else if(!opt.have_height) mode=1;
    } else if(opt.have_width && !opt.have_height) mode=1;
    else if(opt.have_height && !opt.have_width) mode=2;
    if(mode==1) { if(*w<2)*w=2; *h=(int)lroundf(*w/(2.0f*ratio)); if(*h<1)*h=1; }
    if(mode==2) { if(*h<1)*h=1; *w=(int)lroundf(*h*2.0f*ratio); if(*w<2)*w=2; }
    if(!opt.had_size && !opt.have_width && opt.height_count>=3) *w=0;
    if(opt.have_width && !opt.width && opt.using_terminal && opt.terminal==FIT) *w=0;
    if(*w<0 || *h<1) die("Invalid width or height specified\n");
}

static void progress(unsigned scan, unsigned height) {
    int count=(int)(((float)(scan+1)/height)*54);
    if(count>=64) {
        fputs("*** buffer overflow detected ***: terminated\n",stderr);
        fflush(stderr); raise(SIGABRT); _exit(134);
    }
